95	  PruneExpiredTimeSpace(time_space_reservations_, std::chrono::steady_clock::now());
96	  for (const auto& resource_id : resource_ids) {
97	    const auto existing = locks_.find(resource_id);
98	    if (existing != locks_.end() && existing->second != mission_id) {
99	      std::ostringstream oss;
100	      oss << "resource locked: " << resource_id << " by " << existing->second;
101	      result.message = oss.str();
102	      return result;  // 未落任何锁，原子性成立
103	    }
104	  }
105	  // A7：写入前过滤同任务已持有锁与列表内重复，newly_reserved 只记真正新增
106	  std::unordered_set<std::string> counted;
107	  for (const auto& resource_id : resource_ids) {
108	    if (!counted.insert(resource_id).second) {
109	      continue;  // 列表内重复不重复计入
110	    }
111	    const auto existing = locks_.find(resource_id);
112	    if (existing != locks_.end() && existing->second == mission_id) {
113	      continue;  // 同任务已持有，不算新增
114	    }
115	    locks_[resource_id] = mission_id;
116	    result.newly_reserved.push_back(resource_id);
117	  }
118	  std::ostringstream oss;
119	  oss << "reserved " << result.newly_reserved.size() << " resource(s)";
120	  result.success = true;
121	  result.message = oss.str();
122	  return result;
123	}
