125	bool ResourceTable::ReserveTimeSpace(
126	    const std::string& mission_id,
127	    const std::string& resource_id,
128	    std::chrono::steady_clock::time_point start,
129	    std::chrono::steady_clock::time_point end,
130	    std::string* message) {
131	  if (start >= end) {
132	    if (message) *message = "invalid time interval: start >= end";
133	    return false;
134	  }
135	
136	  // M3：入口先剪除过期时空预约，与 Reserve/Release 保持一致——
137	  // 否则已结束的时段仍会参与冲突判断，误拒时间重叠的回溯候选。
138	  PruneExpiredTimeSpace(time_space_reservations_, std::chrono::steady_clock::now());
139	
140	  // 1. 检查是否存在永久排他锁（人工封路等）
141	  if (Locked(resource_id) && Owner(resource_id) != mission_id) {
142	    if (message) *message = "resource statically locked by: " + *Owner(resource_id);
143	    return false;
144	  }
145	
146	  // 2. 检查该资源在目标时间区间内是否与其他任务的预约时段重叠
147	  TimeInterval candidate_interval{start, end};
148	  auto& reservations = time_space_reservations_[resource_id];
149	  for (const auto& res : reservations) {
150	    if (res.mission_id != mission_id && res.interval.OverlapsWith(candidate_interval)) {
151	      if (message) {
152	        *message = "time-space contention on " + resource_id + " with " + res.mission_id;
153	      }
154	      return false;
155	    }
156	  }
157	
158	  // 3. 无时空冲突，落入预约表
159	  reservations.push_back(TimeSpaceReservation{mission_id, resource_id, candidate_interval});
160	  if (message) *message = "time-space reservation confirmed";
161	  return true;
162	}
163	
164	ResourceTable::ReleaseResult ResourceTable::Release(const std::string& mission_id) {
165	  ReleaseResult result;
166	  // A7：入口先剪除过期时空预约
167	  PruneExpiredTimeSpace(time_space_reservations_, std::chrono::steady_clock::now());
168	  for (auto lock = locks_.begin(); lock != locks_.end();) {
169	    if (lock->second == mission_id) {
170	      lock = locks_.erase(lock);
171	      result.released = true;
172	    } else {
173	      ++lock;
174	    }
175	  }
176	
177	  // 清空该任务的所有时空预约
178	  for (auto& [res_id, list] : time_space_reservations_) {
179	    auto before_size = list.size();
180	    list.erase(std::remove_if(list.begin(), list.end(),
181	                              [&mission_id](const TimeSpaceReservation& r) {
182	                                return r.mission_id == mission_id;
183	                              }),
184	               list.end());
185	    if (list.size() < before_size) {
186	      result.released = true;
187	    }
188	  }
189	
190	  result.message =
191	      result.released ? "released resources of " + mission_id : "no resources held by " + mission_id;
192	  return result;
193	}
194	
195	bool ResourceTable::Block(const std::string& resource_id, const std::string& reason,
196	                          std::string* message) {
197	  const std::string owner = std::string(kBlockPrefix) + reason;
198	  const auto existing = locks_.find(resource_id);
199	  if (existing != locks_.end()) {
200	    if (message != nullptr) {
201	      *message = "resource already held: " + resource_id + " by " + existing->second;
202	    }
203	    return false;
204	  }
205	  locks_[resource_id] = owner;
206	  if (message != nullptr) {
207	    *message = "blocked " + resource_id;
208	  }
209	  return true;
210	}
211	
212	bool ResourceTable::Unblock(const std::string& resource_id, std::string* message) {
213	  const auto existing = locks_.find(resource_id);
214	  if (existing == locks_.end()) {
215	    if (message != nullptr) {
216	      *message = "resource not locked: " + resource_id;
217	    }
218	    return false;
219	  }
220	  if (!IsTrafficBlockOwner(existing->second)) {
221	    if (message != nullptr) {
222	      *message = "cannot unblock resource held by mission: " + existing->second;
223	    }
224	    return false;
225	  }
226	  locks_.erase(existing);
227	  if (message != nullptr) {
228	    *message = "unblocked " + resource_id;
229	  }
230	  return true;
231	}
232	
233	bool ResourceTable::Locked(const std::string& resource_id) const {
234	  return locks_.find(resource_id) != locks_.end();
235	}
236	
237	std::optional<std::string> ResourceTable::Owner(const std::string& resource_id) const {
238	  const auto it = locks_.find(resource_id);
239	  if (it == locks_.end()) {
240	    return std::nullopt;
241	  }
242	  return it->second;
243	}
244	
245	std::size_t ResourceTable::TimeSpaceReservationCount() const {
246	  std::size_t total = 0;
247	  for (const auto& entry : time_space_reservations_) {
248	    total += entry.second.size();
249	  }
250	  return total;
251	}
252	
253	std::vector<std::pair<std::string, std::string>> ResourceTable::Snapshot() const {
254	  std::vector<std::pair<std::string, std::string>> out(locks_.begin(), locks_.end());
255	  std::sort(out.begin(), out.end(), [](const auto& lhs, const auto& rhs) {
256	    return lhs.first < rhs.first;
257	  });
258	  return out;
259	}
260	
261	}  // namespace amr_dispatcher_core::dispatcher
