482	                                            const std::string& payload, VehicleEndpoints& ep) {
483	  if (!ep.state_pub) {
484	    return;  // 非法 vehicle_id 已在 EnsureVehicle 告警，该车无 ROS 端点
485	  }
486	  const auto report = amr_dispatcher_core::fleet::DeserializeVda5050State(payload);
487	  if (!report.has_value()) {
488	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
489	                         "丢弃非法 VDA 5050 state 报文 (vehicle=%s)", vehicle_id.c_str());
490	    return;
491	  }
492	  // 无损透传原始 JSON，Task 5 调度侧可用 DeserializeVda5050State 按需解析
493	  std_msgs::msg::String raw;
494	  raw.data = payload;
495	  ep.state_pub->publish(raw);
496	
497	  geometry_msgs::msg::PoseStamped pose;
498	  pose.header.stamp = now();
499	  pose.header.frame_id = "map";
500	  pose.pose.position.x = report->x;
501	  pose.pose.position.y = report->y;
502	  pose.pose.orientation.z = std::sin(report->yaw * 0.5);
503	  pose.pose.orientation.w = std::cos(report->yaw * 0.5);
504	  ep.pose_pub->publish(pose);
505	
506	  if (!ep.online) {
507	    ep.online = true;
508	    std_msgs::msg::Bool online_msg;
509	    online_msg.data = true;
510	    ep.online_pub->publish(online_msg);
511	  }
