1	#pragma once
2	
3	#include <cstdint>
4	#include <optional>
5	#include <string>
6	#include <string_view>
7	
8	namespace amr_dispatcher_core::dispatcher {
9	
10	// 任务生命周期状态：4 态 + 结果分离设计。
11	//
12	//   kPending ──► kActive ──► kFinished
13	//       ▲  │        │  ▲
14	//       │  ▼        ▼  │
15	//       └─ kPaused ◄───┘
16	//
17	// 终态结果（kSucceeded/kFailed/kCanceled）与状态正交，单独记录，
18	// 避免用状态字符串编码结果导致的组合爆炸。
19	enum class MissionState { kPending, kActive, kPaused, kFinished };
20	
21	enum class MissionResult { kNone, kSucceeded, kFailed, kCanceled };
22	
23	// 合法迁移表校验。to==from 一律视为非法（幂等重复到达应被上层去重，而非放行）。
24	bool CanTransition(MissionState from, MissionState to);
25	
26	std::optional<MissionState> ParseMissionState(std::string_view text);
27	std::optional<MissionResult> ParseMissionResult(std::string_view text);
28	std::string_view ToString(MissionState state);
29	std::string_view ToString(MissionResult result);
30	
31	// 一次状态迁移的完整记录，供事件日志与状态机回调复用。
32	struct MissionTransition {
33	  MissionState from = MissionState::kPending;
34	  MissionState to = MissionState::kPending;
35	  std::string message;
36	};
37	
38	// 调度域任务实体。纯数据，ROS 话题转换在 ros 层完成。
39	struct Mission {
40	  std::string id;
41	  std::string order_id;              // 关联业务订单号（批量提交/整单取消用），可空
42	  std::string fleet_id = "default";  // V1.2 多机预留
43	  std::string type = "transport";    // transport / charge / patrol ...
44	  std::string pickup_station;
45	  std::string dropoff_station;
46	  int priority = 0;
47	  std::uint64_t sequence = 0;          // 入队序号，同优先级先到先服务
48	  std::int64_t deadline_unix_ms = 0;   // <=0 表示无截止期
49	  int expected_seconds = 0;            // 预估耗时，供 SJF 类策略
50	  MissionState state = MissionState::kPending;
51	  MissionResult result = MissionResult::kNone;
52	  int attempt = 0;                     // 已执行次数（含重试）
53	  std::string reservation_id;          // 任务当前持有的 traffic 资源 id（可空）
54	};
55	
56	// 状态机封装：所有状态变更必须经过 Transition()，杜绝散落的裸赋值。
57	class MissionStateMachine {
58	 public:
59	  explicit MissionStateMachine(Mission mission = {});
