```cpp
namespace amr_dispatcher_core::workflow {

// Rule 1（Spec §5.3 逐段释放）纯核心计算结果。
struct TrailingUnlockDecision {
  bool confirmed = false;  // lastNodeId 在订单路径上且 sequence 与订单一致
  std::vector<std::string> lock_ids_to_release;  // 严格位于确认位置身后、本任务持有的锁
  std::string message;  // 未确认时的处置指引（confirmed=true 时可为空）
};

// Rule 1：计算应释放的身后路由锁（纯函数，零 ROS）。
//
// 参数:
//   order_path_node_ids: 本单行驶路径（travel order，如 station_A, rn_1, station_B）
//   confirmed_last_node_id: 小车 state.lastNodeId
//   confirmed_last_node_sequence_id: 小车 state.lastNodeSequenceId（订单节点 sequence = 下标 * 2）
//   owner_mission_id: 锁的归属任务（只有 owner相等的锁才可能被释放）
//   held_locks: resource_id -> owner（通常来自 ResourceTable::Snapshot()，
//              可为 const引用构造的临时 map）
//
// 足迹规则（保守）: 确认位置 = path[k] 时，释放 path[0..k-1] 节点锁与
//   path[0..k-2] 边锁；保留 path[k] 节点锁、(k-1,k) 边锁、(k,k+1) 边锁及前方全部锁。
//   lastNodeId 未命中路径 / sequence 与订单不符 -> 不确认，释放集为空。
// 所有权: 仅返回 held_locks 中 owner == owner_mission_id 的锁；他人锁、未持有的锁一律不返回。
TrailingUnlockDecision PlanTrailingUnlock(
    const std::vector<std::string>& order_path_node_ids,
    const std::string& confirmed_last_node_id,
    uint32_t confirmed_last_node_sequence_id,
    const std::string& owner_mission_id,
    const std::unordered_map<std::string, std::string>& held_locks);

// Rule 2（Spec §5.2 断链锁定保护）链路守卫决策（纯函数，零 ROS）。
struct DisconnectGuardDecision {
  bool retain_all_locks = true;   // 铁律：任何链路状态下都不得由守卫产生释放动作
  bool block_new_dispatch = false;
  bool emit_watchdog_warning = false;
  std::string message;
};

DisconnectGuardDecision EvaluateVehicleLinkGuard(bool vehicle_online, bool state_stale);

}  // namespace
```

