    RCLCPP_INFO(get_logger(), "Dynamic unlock: mission %s vehicle %s at %s released %zu lock(s): %s",
                mission_it->first.c_str(), vehicle_id.c_str(), report->last_node_id.c_str(),
                released.size(), joined.c_str());
    if (event_log_) { append evt event "dynamic_unlock" message joined }
